CREATE TABLE "reviews" ("id" text PRIMARY KEY NOT NULL, "order_id" text NOT NULL, "product_id" text NOT NULL, "seller_id" text NOT NULL, "body" text NOT NULL, "buyer_email" text NOT NULL, "rating" integer NOT NULL, "title" text, "status" "review_status" DEFAULT 'pending' NOT NULL, "vendor_response" text, "responded_at" timestamp with time zone, "created_at" timestamp with time zone DEFAULT now() NOT NULL, CONSTRAINT "reviews_order_id_unique" UNIQUE("order_id"), CONSTRAINT "reviews_order_id_orders_id_fk" FOREIGN KEY ("order_id") REFERENCES "orders"("id") ON DELETE NO ACTION ON UPDATE NO ACTION, CONSTRAINT "reviews_product_id_products_id_fk" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE NO ACTION ON UPDATE NO ACTION, CONSTRAINT "reviews_seller_id_sellers_id_fk" FOREIGN KEY ("seller_id") REFERENCES "sellers"("id") ON DELETE NO ACTION ON UPDATE NO ACTION);
